import { config } from '../config/env';
import { languageInfo } from '../data/languages';
import { wordFor } from '../data/levels';
import type { GameObjectDef, LangCode } from '../data/types';
import { audio } from './AudioEngine';

/**
 * Pronunciation pipeline, best source first:
 *   1. an explicit per-object audio file from the level data,
 *   2. a clip pre-generated by `npm run generate:audio` (listed in /audio/manifest.json),
 *   3. the live Fish Audio proxy on the dev/preview server,
 *   4. the browser's own speech synthesis.
 */

let manifest: Promise<Set<string>> | null = null;
function loadManifest() {
  manifest ??= fetch('/audio/manifest.json')
    .then((r) => (r.ok ? r.json() : { files: [] }))
    .then((m: { files?: string[] }) => new Set(m.files ?? []))
    .catch(() => new Set<string>());
  return manifest;
}

let proxy: Promise<boolean> | null = null;
function proxyAvailable() {
  if (!config.ttsProxy) return Promise.resolve(false);
  proxy ??= fetch('/api/tts/status')
    .then((r) => (r.ok ? r.json() : { enabled: false }))
    .then((s: { enabled?: boolean }) => !!s.enabled)
    .catch(() => false);
  return proxy;
}

/** Warm up lookups so the first tap speaks without delay. */
export function primeSpeech() {
  void loadManifest();
  void proxyAvailable();
  if ('speechSynthesis' in window) window.speechSynthesis.getVoices();
}

let generation = 0;

export function stopSpeech() {
  generation++;
  audio.stopVoice();
  if ('speechSynthesis' in window) window.speechSynthesis.cancel();
}

function pickVoice(lang: LangCode): SpeechSynthesisVoice | undefined {
  const tag = languageInfo(lang).bcp47.toLowerCase();
  const voices = window.speechSynthesis.getVoices();
  const base = tag.split('-')[0];
  return (
    voices.find((v) => v.lang.toLowerCase() === tag && /natural|enhanced|premium|google/i.test(v.name)) ??
    voices.find((v) => v.lang.toLowerCase() === tag) ??
    voices.find((v) => v.lang.toLowerCase().startsWith(base))
  );
}

function speakWithBrowser(text: string, lang: LangCode): Promise<void> {
  if (!config.speechFallback || !('speechSynthesis' in window)) return Promise.resolve();
  return new Promise((resolve) => {
    const u = new SpeechSynthesisUtterance(text);
    u.lang = languageInfo(lang).bcp47;
    const voice = pickVoice(lang);
    if (voice) u.voice = voice;
    u.rate = 0.82;
    u.pitch = 1.15;
    const done = () => {
      clearTimeout(guard);
      resolve();
    };
    const guard = setTimeout(done, 4000 + text.length * 120);
    u.onend = done;
    u.onerror = done;
    window.speechSynthesis.speak(u);
  });
}

async function resolveClip(text: string, lang: LangCode, clipId: string | undefined, override: string | undefined) {
  if (audio.isMuted || !audio.context) return null;
  if (override) {
    const buf = await audio.load(override);
    if (buf) return buf;
  }
  if (clipId && (await loadManifest()).has(`${lang}/${clipId}`)) {
    const buf = await audio.load(`/audio/${lang}/${clipId}.mp3`);
    if (buf) return buf;
  }
  if (await proxyAvailable()) {
    return audio.load(`/api/tts?lang=${lang}&text=${encodeURIComponent(text)}`);
  }
  return null;
}

/** Speak a phrase. Resolves when finished (or immediately if superseded or muted). */
export async function say(text: string, lang: LangCode, clipId?: string, override?: string): Promise<void> {
  const mine = ++generation;
  if (audio.isMuted) return;
  const clip = await resolveClip(text, lang, clipId, override);
  if (mine !== generation) return;
  if (clip) await audio.playVoice(clip);
  else await speakWithBrowser(text, lang);
}

const pause = (ms: number) => new Promise((r) => setTimeout(r, ms));

/** English name first, then the word in the language being learned. */
export async function sayObject(obj: GameObjectDef, lang: LangCode): Promise<void> {
  const start = generation + 1;
  await say(obj.name, 'en', obj.id, obj.audio?.en);
  if (lang === 'en' || generation !== start) return;
  await pause(380);
  if (generation !== start) return;
  await say(wordFor(obj, lang), lang, obj.id, obj.audio?.[lang]);
}

export function sayNarration(id: string, text: string) {
  return say(text, 'en', `narration-${id}`);
}

/** Prefetch clips for a page so taps feel instant. */
export async function prefetchObjects(objects: GameObjectDef[], lang: LangCode) {
  if (!audio.context) return;
  const files = await loadManifest();
  for (const obj of objects) {
    for (const l of new Set<LangCode>(['en', lang])) {
      if (files.has(`${l}/${obj.id}`)) void audio.load(`/audio/${l}/${obj.id}.mp3`);
    }
  }
}
